BEGIN;
-- ===== Subject 26: Social Work & Community Services
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published');
UPDATE subjects SET about_title='About Social Work & Community Services', about_body='<p>Social Work and Community Services covers supporting individuals, families and communities. Areas include social work, youth work, community development, social care, child development, gerontology, disability studies, counselling and addiction studies.</p><p>Courses combine theory with supervised placements. Social work is a regulated profession in most countries, so you normally need an accredited degree and local registration (for example Social Work England, AASW or provincial colleges). A degree abroad does not always transfer.</p><p>Check accreditation and registration rules before choosing a course.</p>', why_title='Why study Social Work & Community Services?', why_body='<p><strong>Meaningful work.</strong> You help people through difficult periods and strengthen communities.</p><p><strong>Steady demand.</strong> Ageing populations and mental-health needs increase demand for social care and support.</p><p><strong>Placements built in.</strong> Practical experience is part of the course.</p><p><strong>Regulated pathways.</strong> Registration gives clear professional structures, though rules differ by country.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=26 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Social Work & Community Services', about_body='<p>A Foundation in Social Work &amp; Community Services. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Social Work & Community Services?', why_body='<p>Foundation study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Social Work & Community Services', about_body='<p>A Pathway in Social Work &amp; Community Services. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Social Work & Community Services?', why_body='<p>Pathway study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Social Work & Community Services', about_body='<p>A Diploma in Social Work &amp; Community Services. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Social Work & Community Services?', why_body='<p>Diploma study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Social Work & Community Services', about_body='<p>A Bachelor''s in Social Work &amp; Community Services. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Social Work & Community Services?', why_body='<p>Bachelor''s study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Social Work & Community Services', about_body='<p>A Master''s in Social Work &amp; Community Services. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Social Work & Community Services?', why_body='<p>Master''s study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Social Work & Community Services', about_body='<p>A MBA in Social Work &amp; Community Services. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Social Work & Community Services?', why_body='<p>MBA study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Social Work & Community Services', about_body='<p>A PhD in Social Work &amp; Community Services. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Social Work & Community Services?', why_body='<p>PhD study in Social Work &amp; Community Services lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
