UPDATE subjects SET about_title='About Emerging & Interdisciplinary Subjects', about_body='<p>Emerging and Interdisciplinary Subjects brings together fields that cross traditional boundaries: AI and machine learning, data science, quantum computing, robotics, sustainability and climate, smart cities, immersive technologies, space, nanotechnology and computational social science.</p><p>These areas change quickly, so course content and job titles evolve. Look for programmes with strong research links and industry partners.</p><p>Many are STEM-classified, which can matter for post-study work options in some countries.</p>', why_title='Why study Emerging & Interdisciplinary Subjects?', why_body='<p><strong>Fast-growing fields.</strong> AI, climate and space technologies are attracting investment worldwide.</p><p><strong>Cross-disciplinary skills.</strong> You combine technical, scientific and social perspectives.</p><p><strong>Research-led teaching.</strong> Many programmes are linked to active labs and start-ups.</p><p><strong>Future-facing careers.</strong> Roles in these fields are new and evolving, with room to shape the field.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=30 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Emerging & Interdisciplinary Subjects', about_body='<p>A Foundation in Emerging &amp; Interdisciplinary Subjects. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Emerging & Interdisciplinary Subjects?', why_body='<p>Foundation study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Emerging & Interdisciplinary Subjects', about_body='<p>A Pathway in Emerging &amp; Interdisciplinary Subjects. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Emerging & Interdisciplinary Subjects?', why_body='<p>Pathway study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Emerging & Interdisciplinary Subjects', about_body='<p>A Diploma in Emerging &amp; Interdisciplinary Subjects. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Emerging & Interdisciplinary Subjects?', why_body='<p>Diploma study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Emerging & Interdisciplinary Subjects', about_body='<p>A Bachelor''s in Emerging &amp; Interdisciplinary Subjects. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Emerging & Interdisciplinary Subjects?', why_body='<p>Bachelor''s study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Emerging & Interdisciplinary Subjects', about_body='<p>A Master''s in Emerging &amp; Interdisciplinary Subjects. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Emerging & Interdisciplinary Subjects?', why_body='<p>Master''s study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Emerging & Interdisciplinary Subjects', about_body='<p>A MBA in Emerging &amp; Interdisciplinary Subjects. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Emerging & Interdisciplinary Subjects?', why_body='<p>MBA study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Emerging & Interdisciplinary Subjects', about_body='<p>A PhD in Emerging &amp; Interdisciplinary Subjects. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Emerging & Interdisciplinary Subjects?', why_body='<p>PhD study in Emerging &amp; Interdisciplinary Subjects lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
COMMIT;