INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=26 AND status='published'),'about','About Rehabilitation Studies',NULL,'<p>Rehabilitation Studies focuses on supporting recovery and independence after illness or injury. It sits within Social Work &amp; Community Services and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND name='Rehabilitation Studies'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=26 AND status='published'),'why','Why study Rehabilitation Studies?',NULL,'<p>Rehabilitation Studies builds specialist skills in supporting recovery and independence after illness or injury. Typical graduate roles include rehabilitation support worker, case manager, community-rehabilitation officer. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=26 AND status='published') AND name='Rehabilitation Studies'));
