INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=27 AND status='published'),'about','About Warehouse Management',NULL,'<p>Warehouse Management focuses on running storage, inventory and fulfilment centres. It sits within Transport &amp; Logistics and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=27 AND status='published') AND name='Warehouse Management'));
