INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=28 AND status='published'),'about','About Hydrogen Energy',NULL,'<p>Hydrogen Energy focuses on producing, storing and using hydrogen as a fuel. It sits within Energy, Oil &amp; Gas and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=28 AND status='published') AND name='Hydrogen Energy'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=28 AND status='published'),'why','Why study Hydrogen Energy?',NULL,'<p>Hydrogen Energy builds specialist skills in producing, storing and using hydrogen as a fuel. Typical graduate roles include hydrogen engineer, energy-systems analyst, project engineer. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=28 AND status='published') AND name='Hydrogen Energy'));
