INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,study_level_id) SELECT gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=30 AND status='published'),'destination','United States',NULL,'<p>Major hub for AI, space and advanced-technology research.</p><p>Graduates can work on OPT for 12 months, with a 24-month STEM extension for eligible degrees. Visa and work-fee rules (OPT and H-1B) are under active review, so check USCIS before planning. International tuition is commonly $25,000–$65,000 a year.</p>','published',1,(SELECT id FROM study_levels WHERE slug='masters') WHERE EXISTS (SELECT 1 FROM subject_study_levels x WHERE x.subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND x.study_level_id=(SELECT id FROM study_levels WHERE slug='masters'));
