INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=30 AND status='published'),'about','About Materials Science',NULL,'<p>Materials Science focuses on structure and properties of metals, polymers, ceramics and composites. It sits within Emerging &amp; Interdisciplinary Subjects and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND name='Materials Science'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=30 AND status='published'),'why','Why study Materials Science?',NULL,'<p>Materials Science builds specialist skills in structure and properties of metals, polymers, ceramics and composites. Typical graduate roles include materials scientist, R&amp;D scientist, failure analyst. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=30 AND status='published') AND name='Materials Science'));
